'use strict';

const {
    test
  } = require('node:test'),
  assert = require('node:assert/strict'),
  Official = require('../src/official-direct.cjs');
function png() {
  const b = new Uint8Array(24);
  b.set([137, 80, 78, 71, 13, 10, 26, 10]);
  const v = new DataView(b.buffer);
  v.setUint32(16, 1216);
  v.setUint32(20, 832);
  return b;
}
test('official request uses native img2img, original dimensions, explicit seed and reference image bytes', () => {
  const source = png(),
    body = Official.requestBody({
      prompt: '5::closed eyes::',
      requestedSeed: 123,
      options: {
        negativePrompt: 'lowres'
      }
    }, source);
  assert.equal(body.action, 'img2img');
  assert.equal(body.model, 'nai-diffusion-4-5-full');
  assert.equal(body.parameters.width, 1216);
  assert.equal(body.parameters.height, 832);
  assert.equal(body.parameters.noise_schedule, 'exponential');
  assert.equal(body.parameters.seed, 123);
  assert.equal(body.parameters.negative_prompt, 'lowres');
  assert.deepEqual(Official.decode(body.parameters.image), source);
  assert.equal(body.parameters.v4_prompt.caption.base_caption, body.input);
});
test('missing API key stops before network and never falls back to host image generation', async () => {
  let network = 0;
  const original = global.fetch;
  global.fetch = async () => {
    network++;
    throw Error('unexpected');
  };
  try {
    await assert.rejects(Official.generate({
      variable: {
        get: async () => null
      }
    }, {
      options: {}
    }, {
      id: 'x'
    }, async () => {}), /API/);
    assert.equal(network, 0);
  } finally {
    global.fetch = original;
  }
});
test('official PNG ZIP extraction validates stored entries', async () => {
  const bytes = png(),
    name = new TextEncoder().encode('image.png'),
    local = new Uint8Array(30 + name.length + bytes.length),
    lv = new DataView(local.buffer);
  lv.setUint32(0, 0x04034b50, true);
  lv.setUint32(18, bytes.length, true);
  lv.setUint32(22, bytes.length, true);
  lv.setUint16(26, name.length, true);
  local.set(name, 30);
  local.set(bytes, 30 + name.length);
  const central = new Uint8Array(46 + name.length),
    cv = new DataView(central.buffer);
  cv.setUint32(0, 0x02014b50, true);
  cv.setUint32(20, bytes.length, true);
  cv.setUint32(24, bytes.length, true);
  cv.setUint16(28, name.length, true);
  central.set(name, 46);
  const end = new Uint8Array(22),
    ev = new DataView(end.buffer);
  ev.setUint32(0, 0x06054b50, true);
  ev.setUint16(10, 1, true);
  ev.setUint32(16, local.length, true);
  const zip = new Uint8Array(local.length + central.length + end.length);
  zip.set(local);
  zip.set(central, local.length);
  zip.set(end, local.length + central.length);
  assert.deepEqual(await Official.unzipPng(zip), bytes);
  await assert.rejects(Official.unzipPng(new Uint8Array(24)), /ZIP/);
});
test('default strength is 0.85 and explicit changes do not change identity transport settings', () => {
  const compiled = {
      prompt: '5::closed eyes::',
      requestedSeed: 123,
      options: {}
    },
    a = Official.requestBody(compiled, png()),
    b = Official.requestBody(compiled, png(), 0.45);
  assert.equal(a.parameters.strength, 0.85);
  assert.equal(b.parameters.strength, 0.45);
  assert.deepEqual({
    ...a.parameters,
    strength: 0
  }, {
    ...b.parameters,
    strength: 0
  });
  assert.equal(Official.requestBody(compiled, png(), 0.9).parameters.strength, 0.9);
  assert.throws(() => Official.requestBody(compiled, png(), 0.91), /变化强度/);
});
test('official and third-party profiles never share credentials or endpoint', () => {
  const cfg = {
    apiKey: 'official-test-key',
    thirdParty: {
      apiKey: 'relay-test-key',
      url: 'https://api.hamubox.com/v1/novelai'
    }
  };
  assert.equal(Official.connectionProfile(cfg, 'official').apiKey, 'official-test-key');
  const relay = Official.connectionProfile(cfg, 'thirdparty');
  assert.equal(relay.apiKey, 'relay-test-key');
  assert.equal(relay.endpoint, 'https://api.hamubox.com/v1/novelai/ai/generate-image');
  assert.equal(Official.connectionProfile({
    apiKey: 'official-only'
  }, 'thirdparty').apiKey, '');
  assert.throws(() => Official.endpoint('https://user:key@example.com/v1'));
  assert.throws(() => Official.endpoint('https://example.com/?key=secret'));
});
test('fixed seed survives target action changes and img2img still receives the source', () => {
  const a = Official.requestBody({
      prompt: 'open eyes',
      requestedSeed: 1953028770,
      options: {}
    }, png()),
    b = Official.requestBody({
      prompt: '5::closed eyes::',
      requestedSeed: 1953028770,
      options: {}
    }, png());
  assert.equal(a.parameters.seed, b.parameters.seed);
  assert.notEqual(a.input, b.input);
  assert.equal(a.parameters.image, b.parameters.image);
  assert.equal(b.action, 'img2img');
});
test('third-party address has no default and is required before network use', () => {
  assert.equal(Official.DEFAULT_RELAY, '');
  assert.equal(Official.connectionProfile({
    provider: 'thirdparty',
    thirdParty: {
      apiKey: 'test-relay-key'
    }
  }).endpoint, '');
  assert.throws(() => Official.endpoint(''), /中转\s*API\s*地址/);
});
test('relay static native request uses generate action, high quality and no source image fields', () => {
  const body = Official.staticRequestBody({
    prompt: 'base | person',
    options: {
      negativePrompt: 'lowres'
    },
    requestedSeed: 0
  }, {
    width: 832,
    height: 1216,
    steps: 28,
    scale: 6,
    sampler: 'k_euler'
  });
  assert.equal(body.action, 'generate');
  assert.equal(body.parameters.width, 832);
  assert.equal(body.parameters.height, 1216);
  assert.equal(body.parameters.qualityToggle, true);
  assert.equal(body.parameters.seed, 0);
  assert.equal(body.parameters.image, undefined);
  assert.equal(body.parameters.strength, undefined);
  assert.equal(body.parameters.noise, undefined);
});
test('HTTP 401 reports actual mode and static transport sends text-to-image without loading reference', async () => {
  const original = global.fetch;
  try {
    for (const staticDirect of [true, false]) {
      let calls = 0,
        loads = 0;
      global.fetch = async (url, options) => {
        calls++;
        const body = JSON.parse(options.body);
        assert.equal(body.action, staticDirect ? 'generate' : 'img2img');
        assert.equal(Object.hasOwn(body.parameters, 'image'), !staticDirect);
        assert.equal(options.headers.Authorization, 'Bearer relay-test-key');
        return {
          ok: false,
          status: 401,
          headers: {
            get: () => null
          },
          text: async () => ''
        };
      };
      const tavo = {
        variable: {
          get: async () => ({
            thirdParty: {
              url: 'https://example.com/v1/novelai',
              apiKey: 'relay-test-key'
            }
          })
        },
        file: {
          load: async () => {
            loads++;
            return Official.encode(png());
          }
        }
      };
      await assert.rejects(Official.generate(tavo, {
        staticDirect,
        directProvider: 'thirdparty',
        prompt: 'portrait',
        options: staticDirect ? {} : {
          referenceImages: ['source.png']
        }
      }, {
        id: 'test'
      }, async () => {}), e => e.message.includes((staticDirect ? '文生图' : '图生图') + ' API 返回 HTTP 401') && e.message.includes('鉴权失败'));
      assert.equal(calls, 1);
      assert.equal(loads, staticDirect ? 0 : 1);
    }
  } finally {
    global.fetch = original;
  }
});
test('actual HTTP transport selects independent static and motion credentials and endpoints', async () => {
  const original = global.fetch;
  try {
    for (const staticDirect of [true, false]) {
      global.fetch = async (url, options) => {
        assert.equal(url, staticDirect ? Official.ENDPOINT : 'https://motion.example/v1/novelai/ai/generate-image');
        assert.equal(options.headers.Authorization, 'Bearer ' + (staticDirect ? 'pst-static-test-key-12345' : 'motion-test-key-123456'));
        assert.equal(JSON.parse(options.body).action, staticDirect ? 'generate' : 'img2img');
        return {
          ok: false,
          status: 401,
          headers: {
            get: () => null
          },
          text: async () => ''
        };
      };
      const tavo = {
        variable: {
          get: async name => name === 'aozora_motion_connection_v1' ? {
            provider: 'thirdparty',
            thirdParty: {
              url: 'https://motion.example/v1/novelai',
              apiKey: 'motion-test-key-123456'
            }
          } : {
            provider: 'official',
            apiKey: 'pst-static-test-key-12345'
          }
        },
        file: {
          load: async () => Official.encode(png())
        }
      };
      await assert.rejects(Official.generate(tavo, {
        staticDirect,
        prompt: 'portrait',
        options: staticDirect ? {} : {
          referenceImages: ['source.png']
        }
      }, {
        id: 'independent'
      }, async () => {}), /HTTP 401/);
    }
  } finally {
    global.fetch = original;
  }
});
