test('NAI 4.5 edit reports provider validation errors without leaking the API key', async () => {
  const key='test-provider-key-private';
  const original=global.fetch;
  const payloads=[
    {error:{code:'INVALID_IMAGE_PARAMETERS',message:'Unsupported sampler for '+key}},
    {detail:[{loc:['body','parameters','noise'],type:'value_error',msg:'Invalid noise',input:key}]}
  ];
  global.fetch=async()=>new Response(JSON.stringify(payloads.shift()),{
    status:400,headers:{'Content-Type':'application/json'}
  });
  const tavo={
    variable:{get:async()=>({provider:'thirdparty',thirdParty:{url:'https://relay.example/native',apiKey:key}})},
    file:{load:async()=>Official.encode(png())}
  };
  const compiled={syntax:'nai45-original-edit',prompt:'solo portrait',options:{referenceImages:['source.png']}};
  try{
    for(const expected of [/INVALID_IMAGE_PARAMETERS.*Unsupported sampler/,/body\.parameters\.noise.*Invalid noise/]){
      await assert.rejects(Official.generate(tavo,compiled,{id:'edit'},async()=>{}),error=>{
        assert.equal(error.code,'IMAGE_HTTP_ERROR');
        assert.equal(error.statusCode,400);
        assert.match(error.message,expected);
        assert.ok(!error.message.includes(key));
        return true;
      });
    }
  }finally{global.fetch=original;}
});
